import{_ as c,o as t,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — Invite Agency Member (FR 3.4.7)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-7-invite-agency-member/plan.md","filePath":"feature/agency-workspace/3-4-7-invite-agency-member/plan.md"}'),i={name:"feature/agency-workspace/3-4-7-invite-agency-member/plan.md"};function a(d,e,r,l,s,h){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="plan-—-invite-agency-member-fr-3-4-7" tabindex="-1">Plan — Invite Agency Member (FR 3.4.7) <a class="header-anchor" href="#plan-—-invite-agency-member-fr-3-4-7" aria-label="Permalink to &quot;Plan — Invite Agency Member (FR 3.4.7)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho Owner mời người khác vào Agency qua email, hết hạn 1-30 ngày (mặc định 30).</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>AgencyServiceImpl.inviteMember()</code></td></tr><tr><td>File đã có</td><td><code>AgencyController</code> (<code>POST /{agencyId}/invitations</code>), <code>InviteAgencyMemberRequest</code>, <code>AgencyInvitation</code>, <code>MailService</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/agencies/{agencyId}/invitations</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>Body: { &quot;email&quot;: &quot;string&quot;, &quot;inviteeName&quot;?, &quot;note&quot;?, &quot;workspaceId&quot;?, &quot;role&quot;? (MANAGER|CREATOR|CLIENT), &quot;expiryDays&quot;? (1-30, default 30) }</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;AgencyInvitationResponse&gt;</span></span>
<span class="line"><span>   data = { id, agencyId, agencyName, invitedEmail, invitedBy, token, note, workspaceId, workspaceName, role, status, expiresAt, acceptedAt, createdAt }</span></span></code></pre></div><p>Khác so với spec.md (đề xuất <code>201</code> + <code>{invitationId, expiresAt}</code>):</p><ul><li><strong>Trả <code>200</code> (không <code>201</code>)</strong> — controller dùng <code>ApiResponse.ok</code>, không gắn <code>@ResponseStatus(CREATED)</code>. Giữ thống nhất với các endpoint khác.</li><li><strong>Response đầy đủ <code>AgencyInvitationResponse</code></strong> kèm <code>token</code> (để FE dựng invite link) thay vì chỉ <code>{invitationId, expiresAt}</code>.</li><li><strong>Gửi email kèm token link</strong> thay vì notification in-app — <code>MailService.sendAgencyInvitationEmail</code> gửi link <code>/invitations/accept?token=...</code>. Notification in-app chưa có service (ngoài scope).</li></ul><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li>Đọc <code>agencies</code> (owner-check), <code>users</code> (check đã là member), <code>agency_members</code>, <code>agency_invitations</code>.</li><li>Ghi <code>agency_invitations</code>: <code>token = UUID</code>, <code>status = PENDING</code>, <code>expiresAt = now + expiryDays</code> (1-30, mặc định 30, clamp nếu ngoài khoảng).</li><li>Đọc thêm <code>workspaces</code>, <code>workspace_members</code> khi request có <code>workspaceId</code>/<code>role</code> (validate workspace thuộc agency, check MANAGER chưa được gán).</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><ol><li><code>findAgencyOrThrow</code> → 404; owner-check → 403 <code>NOT_AGENCY_OWNER</code>.</li><li><code>email = request.email().trim().toLowerCase()</code>.</li><li>Check đã là member → 409 <code>ALREADY_AGENCY_MEMBER</code>.</li><li>Check đã có invitation PENDING còn hạn → 409 <code>INVITATION_ALREADY_PENDING</code>.</li><li>Check tổng invitation PENDING còn hạn của agency ≥ 20 → 409 <code>TOO_MANY_PENDING_INVITATIONS</code>.</li><li>Nếu có <code>workspaceId</code>: check workspace thuộc agency (400 <code>WORKSPACE_NOT_IN_AGENCY</code>); nếu <code>role == MANAGER</code>, check workspace chưa có manager active (409 <code>MANAGER_ALREADY_ASSIGNED</code>).</li><li>Nếu <code>role == CLIENT</code> mà không có <code>workspaceId</code> → 400 <code>WORKSPACE_REQUIRED_FOR_CLIENT_INVITE</code>.</li><li>Build + save invitation (<code>expiresAt = now + clamp(expiryDays, 1, 30)</code>) → <code>sendAgencyInvitationEmail</code>.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>AgencyInvitation</code> entity, <code>MailService</code> (đã có)</td></tr><tr><td>Bị chặn</td><td><code>View Invitation Status</code> (3.4.8), <code>acceptInvitation</code> (luồng mời)</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Email chưa có User account (spec mục 7):</strong> vẫn gửi được invite (invite gắn <code>invitedEmail</code>, không cần User tồn tại). Trước 2026-10-26, user phải tự bấm link email để <code>acceptInvitation</code> xác thực — chưa có bước tự động nào khi vừa đăng ký xong. Đã thêm <code>AgencyServiceImpl.autoAcceptPendingInvitations(User)</code>, gọi từ <code>AuthServiceImpl.verifyOtp()</code> ngay sau khi set <code>emailVerifiedAt</code>: tự động accept mọi invite PENDING còn hạn khớp <code>invitedEmail == user.email</code>, trừ role CLIENT (vẫn cần chọn ClientProfile thủ công qua <code>acceptClientInvitation</code>) và role MANAGER gán sẵn workspace (giữ an toàn, tránh double-manager — vẫn cần accept thủ công để chạy <code>assertNoManagerYet</code>).</li><li><strong>Trùng email pending:</strong> chặn bằng <code>INVITATION_ALREADY_PENDING</code> (tránh spam 2 lời mời cùng email).</li></ul><h2 id="_7-v2-2026-10-02-—-invite-client-tu-trang-rieng-auto-suggest" tabindex="-1">7. V2 (2026-10-02) — Invite CLIENT từ trang riêng + auto-suggest <a class="header-anchor" href="#_7-v2-2026-10-02-—-invite-client-tu-trang-rieng-auto-suggest" aria-label="Permalink to &quot;7. V2 (2026-10-02) — Invite CLIENT từ trang riêng + auto-suggest&quot;">​</a></h2><ul><li>Trang <code>/workspaces/:id/clients</code> (mới, tách khỏi <code>/workspaces/:id/members</code>) gọi cùng cơ chế <code>WorkspaceService.inviteMember(workspaceId, {email, role: &quot;CLIENT&quot;, note})</code> → <code>WorkspaceInvitation</code> (khác bảng <code>AgencyInvitation</code> ở §2 nhưng cùng accept flow qua <code>AgencyServiceImpl.acceptInvitation</code> nhánh fallback WorkspaceInvitation).</li><li><strong>API mới</strong>: <code>GET /api/v1/agencies/{agencyId}/invite-lookup?email=</code> → <code>AgencyServiceImpl.inviteLookup</code>. Trả <code>{userExists, isAlreadyClientInAgency, existingWorkspaces[]}</code> — query <code>clientProfileRepository.findByUserId</code> rồi <code>workspaceMemberRepository.findByClientProfileIdInAndIsActiveTrue</code> lọc theo <code>workspace.agencyId == agencyId</code>. Chỉ advisory, FE hiển thị gợi ý inline, không tự động thêm.</li><li>Accept CLIENT: <code>AgencyServiceImpl.resolveClientProfileForAccept</code> — chọn <code>clientProfileId</code> có sẵn (check <code>CLIENT_PROFILE_NOT_OWNED</code> nếu không phải của mình) hoặc <code>newClientProfile</code> tạo mới; bắt buộc 1 trong 2, nếu không → <code>CLIENT_PROFILE_REQUIRED_FOR_ACCEPT</code>.</li></ul>`,18)])])}const u=c(i,[["render",a]]);export{g as __pageData,u as default};
